import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data, rows, cols):
        self.matrix = ctypes.c_void_p()
        self.rows = rows
        self.cols = cols
        self.data = data

    def __del__(self):
        if self.matrix:
            gsl.gsl_matrix_free(ctypes.byref(self.matrix))

    @property
    def data_ptr(self):
        return self.matrix

    @data_ptr.setter
    def data_ptr(self, value):
        self.matrix = value

    def to_numpy(self):
        result = np.zeros((self.rows, self.cols), dtype=np.float64)
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = gsl.gsl_matrix_get(self.matrix, i, j)
        return result

    def from_numpy(self, np_array):
        self.rows = np_array.shape[0]
        self.cols = np_array.shape[1]
        self.matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.matrix, i, j, np_array[i][j])

