import ctypes
import math

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

def integrate(function, a, b, epsabs, epsrel):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function type
    func_type = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)

    # Convert the Python function to a C function
    c_function = func_type(function)

    # Define the structure for the result
    class Result(ctypes.Structure):
        _fields_ = [
            ("result", ctypes.c_double),
            ("abs_err", ctypes.c_double),
            ("neval", ctypes.c_int)
        ]

    # Call the GSL integration function
    result = Result()
    gsl.gsl_integration_qng.argtypes = [func_type, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(Result)]
    gsl.gsl_integration_qng(c_function, a, b, epsabs, epsrel, ctypes.byref(result))

    return result.result, result.abs_err, result.neval


def f1(x):
    return math.sin(x)

def f2(x):
    return math.exp(-x)

def f3(x):
    return 1.0 / (1.0 + x*x)

