    # Test case 2: integrate exp(-x) from 0 to infinity (approximated)
    result2, error2, evals2 = integrate(GSLFunction(f2), 0.0, 1000.0, 1e-10, 1e-10)
    print(f"Test 2: Integral of exp(-x) from 0 to 1000: {result2}, Error: {error2}, Evaluations: {evals2}")

    # Test case 3: integrate 1/(1+x^2) from -infinity to infinity (pi)
    result3, error3, evals3 = integrate(GSLFunction(f3), -1000.0, 1000.0, 1e-10, 1e-10)
