class GSLPolyComplexWorkspace:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    _lib.gsl_poly_complex_solve.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]
    _lib.gsl_poly_complex_solve.restype = ctypes.c_int

    def __init__(self, n):
        self.n = n
        self.root = (ctypes.c_double * (2 * n))()
        self.workspace = self._lib.gsl_poly_complex_workspace_alloc(n)

    def __del__(self):
        self._lib.gsl_poly_complex_workspace_free(self.workspace)

    def compute_complex_roots(self, coefficients):
        if len(coefficients) < 2:
            raise ValueError("Coefficients must have at least 2 elements for a polynomial of degree >= 1")

        coeff_ptr = (ctypes.c_double * len(coefficients))(*coefficients)
        roots = (ctypes.c_double * (2 * self.n))()
        status = self._lib.gsl_poly_complex_solve(coeff_ptr, self.n, self.workspace, roots, ctypes.pointer(ctypes.c_int()))

        if status != 0:
            raise RuntimeError(f"Error in gsl_poly_complex_solve: {status}")

        roots_list = []
        for i in range(self.n):
            real = roots[2 * i]
            imag = roots[2 * i + 1]
            roots_list.append(complex(real, imag))

        return roots_list


def compute_complex_roots(coefficients):
    if not isinstance(coefficients, list):
        raise TypeError("Input must be a list")
    if not all(isinstance(c, (int, float)) for c in coefficients):
        raise TypeError("All elements in coefficients must be numbers")

    n = len(coefficients) - 1
    workspace = GSLPolyComplexWorkspace(n)
    return workspace.compute_complex_roots(coefficients)

