import math

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def callback(self, x):
        return self.func(x)

    def f1(self, x):
        return math.sin(x)

    def f2(self, x):
        return math.exp(-x)

    def f3(self, x):
        return 1.0 / (1.0 + x*x)

class GSLIntegrationWorkspace:
    def __init__(self):
        self.workspace = ctypes.c_void_p()

    def __del__(self):
        if self.workspace:
            gsl.gsl_integration_workspace_free(ctypes.byref(self.workspace))

    def allocate(self, limit):
        gsl.gsl_integration_workspace_alloc(limit, ctypes.byref(self.workspace))

    def free(self):
        gsl.gsl_integration_workspace_free(ctypes.byref(self.workspace))

    def integrate(self, function, a, b, epsabs, epsrel, limit, key):
        result = ctypes.c_double()
        error = ctypes.c_double()
        gsl.gsl_integration_qag(ctypes.byref(function), ctypes.byref(a), ctypes.byref(b), ctypes.byref(epsabs), ctypes.byref(epsrel), ctypes.byref(limit), ctypes.byref(key), ctypes.byref(self.workspace), ctypes.byref(result), ctypes.byref(error))
        return result.value, error.value

