import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)

    def to_gsl(self):
        gsl_matrix = ctypes.create_string_buffer(ctypes.c_size_t(self.size * self.size).value * ctypes.sizeof(ctypes.c_double))
        ptr = ctypes.pointer(gsl_matrix)
        for i in range(self.size):
            for j in range(self.size):
                ctypes.memmove(ctypes.addressof(ptr.contents.data[i * self.size + j]), 
                               ctypes.c_double(self.data[i][j]).value,
                               ctypes.c_size_t(ctypes.sizeof(ctypes.c_double)).value)
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        self.data = [[0.0 for _ in range(self.size)] for _ in range(self.size)]
        for i in range(self.size):
            for j in range(self.size):
                self.data[i][j] = ctypes.c_double(ctypes.addressof(gsl_matrix.contents.data[i * self.size + j])).value

    def __str__(self):
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).to_gsl()

