import ctypes
import numpy as np

class GSLSpMatrix:
    _lib = None

    @classmethod
    def init_lib(cls):
        if cls._lib is None:
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    @classmethod
    def create_sparse_matrix(cls, rows, cols):
        cls.init_lib()
        matrix = cls._lib.gsl_spmatrix_create(rows, cols)
        return ctypes.c_void_p(matrix)

    @classmethod
    def set_sparse_matrix_element(cls, matrix, row, col, value):
        cls.init_lib()
        cls._lib.gsl_spmatrix_set(matrix, row, col, value)

    @classmethod
    def get_sparse_matrix_elements(cls, matrix):
        cls.init_lib()
        rows = ctypes.c_size_t()
        cols = ctypes.c_size_t()
        cls._lib.gsl_spmatrix_get_size(matrix, ctypes.byref(rows), ctypes.byref(cols))
        data = (ctypes.c_double * (rows.value * cols.value))()
        indices = (ctypes.c_int * (rows.value * cols.value))()
        I = (ctypes.c_int * (rows.value * cols.value))()
        J = (ctypes.c_int * (rows.value * cols.value))()
        cls._lib.gsl_spmatrix_get_data(matrix, data, indices, I, J)
        elements = []
        for i in range(rows.value):
            for j in range(cols.value):
                elements.append((I[i], J[i], data[i]))
        return elements

    @classmethod
    def swap_sparse_matrix_elements(cls, matrix, i, j):
        cls.init_lib()
        cls._lib.gsl_spmatrix_swap(matrix, i, j)

if __name__ == "__main__":
    rows = 3
    cols = 3
    matrix = GSLSpMatrix.create_sparse_matrix(rows, cols)
    GSLSpMatrix.set_sparse_matrix_element(matrix, 0, 0, 1.0)
    GSLSpMatrix.set_sparse_matrix_element(matrix, 1, 1, 2.0)
    GSLSpMatrix.set_sparse_matrix_element(matrix, 2, 2, 3.0)

    print("Before swap:")
    elements = GSLSpMatrix.get_sparse_matrix_elements(matrix)
    for row, col, val in elements:
        print(f"({row}, {col}): {val}")

    i, j = 0, 1
    GSLSpMatrix.swap_sparse_matrix_elements(matrix, i, j)

    print("After swap:")
    elements = GSLSpMatrix.get_sparse_matrix_elements(matrix)
    for row, col, val in elements:
        print(f"({row}, {col}): {val}")

