import ctypes

class GSLMatrix:
    _lib = None
    _gsl_matrix = None

    @classmethod
    def init_lib(cls):
        if cls._lib is None:
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    @classmethod
    def create_gsl_matrix(cls, data):
        cls.init_lib()
        matrix = cls._lib.gsl_matrix_alloc(2, 2)
        for i in range(2):
            for j in range(2):
                cls._lib.gsl_matrix_set(matrix, i, j, data[i][j])
        return matrix

    @classmethod
    def retrieve_gsl_matrix(cls, gsl_matrix):
        cls.init_lib()
        data = [[0.0 for _ in range(2)] for _ in range(2)]
        for i in range(2):
            for j in range(2):
                data[i][j] = cls._lib.gsl_matrix_get(gsl_matrix, i, j)
        return data

    @classmethod
    def free_gsl_matrix(cls, gsl_matrix):
        cls.init_lib()
        cls._lib.gsl_matrix_free(gsl_matrix)

# Example usage
